#!/usr/bin/env sh
# Creates ops/.env with fresh random secrets, once. Never overwrites an
# existing file. Any variable already set in the environment is used as-is,
# e.g. to keep a local database volume's password:
#   POSTGRES_PASSWORD=filspay_dev_password ops/init-env.sh
set -eu
cd "$(dirname "$0")"
if [ -f .env ]; then
  echo "ops/.env already exists; leaving it alone." >&2
  exit 0
fi
umask 077
cat > .env <<EOF
# Generated by ops/init-env.sh on $(date -u +%Y-%m-%dT%H:%M:%SZ). Not in git (see .gitignore).
POSTGRES_PASSWORD=${POSTGRES_PASSWORD:-$(openssl rand -hex 24)}
WEBHOOK_SECRET_ENCRYPTION_KEY=${WEBHOOK_SECRET_ENCRYPTION_KEY:-$(openssl rand -base64 32)}
SETTLEMENT_INTERNAL_TOKEN=${SETTLEMENT_INTERNAL_TOKEN:-$(openssl rand -hex 32)}
ACQUIRER_CALLBACK_SIGNING_SECRET=${ACQUIRER_CALLBACK_SIGNING_SECRET:-$(openssl rand -hex 32)}
# Public hostname (Caddy gets certificates for it and admin.<it>), e.g.
# 165-232-180-63.sslip.io; laptops leave the default.
PUBLIC_HOST=${PUBLIC_HOST:-localhost}
# true only on the hosted demo sandbox (no OTP delivery channel exists): see ops/README.md
OTP_DEV_EXPOSE=${OTP_DEV_EXPOSE:-false}
EOF
echo "Wrote ops/.env. Keep a copy somewhere safe: losing WEBHOOK_SECRET_ENCRYPTION_KEY makes stored webhook secrets unreadable."
